INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20601, 'គណនាដេរីវេនៃ \(f(x)=3 x^{2} - 5 x + 1\)។', NULL, '["\\(6 x\\)", "\\(6 x - 5\\)", "\\(3 x - 5\\)", "\\(6 x + 5\\)"]', 1, NULL, 1, 'mcq', 'ដេរីវេពហុធា ៖ \((3x^2)''=6x\), \((-5x)''=-5\) ដូច្នេះ \(f''(x)=6x-5\) (ហើយ \(f''(2)=7\))។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20602, 'គណនាដេរីវេនៃ \(y=\sin{\left(3 x \right)}\)។', NULL, '["\\(3 \\cos{\\left(3 x \\right)}\\)", "\\(- 3 \\cos{\\left(3 x \\right)}\\)", "\\(\\cos{\\left(3 x \\right)}\\)", "\\(3 \\sin{\\left(3 x \\right)}\\)"]', 0, NULL, 1, 'mcq', '\((\sin u)''=u''\cos u\) ជាមួយ \(u=3x\) ៖ \(y''=3\cos3x\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20603, 'គណនាដេរីវេនៃ \(y=\operatorname{asin}{\left(x \right)}\)។', NULL, '["\\(- \\dfrac{1}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{1}{\\sqrt{x^{2} + 1}}\\)", "\\(\\dfrac{1}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{1}{x^{2} + 1}\\)"]', 2, NULL, 1, 'mcq', '\(\dfrac{d}{dx}(\sin^{-1}x)=\dfrac1{\sqrt{1-x^2}}\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20604, 'គណនាដេរីវេទី ២ នៃ \(y=x^{4} - 3 x^{2}\)។', NULL, '["\\(12 x^{3}\\)", "\\(4 x^{3} - 6 x\\)", "\\(12 x^{2} - 6 x\\)", "\\(12 x^{2} - 6\\)"]', 3, NULL, 1, 'mcq', '\(y''=4x^3-6x\) ហើយ \(y''''=12x^2-6\)។', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20605, 'គណនាដេរីវេនៃ \(f(x)=\dfrac{1}{x}\)។', NULL, '["\\(- \\dfrac{1}{x^{2}}\\)", "\\(- \\dfrac{1}{x}\\)", "\\(\\dfrac{1}{x}\\)", "\\(\\dfrac{1}{x^{2}}\\)"]', 0, NULL, 1, 'mcq', '\(\left(x^{-1}\right)''=-x^{-2}=-\dfrac1{x^2}\)។', 'ដេរីវេលំដាប់ខ្ពស់', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20606, 'គណនាដេរីវេនៃ \(y=\left(x^{2} + 1\right)^{3}\)។', NULL, '["\\(3 \\left(x^{2} + 1\\right)^{2}\\)", "\\(3 x \\left(x^{2} + 1\\right)^{2}\\)", "\\(6 x \\left(x^{2} + 1\\right)^{2}\\)", "\\(6 x \\left(x^{2} + 1\\right)^{3}\\)"]', 2, NULL, 1, 'mcq', 'តាង \(u=x^2+1\) ៖ \(y''=3u^2\cdot u''=3(x^2+1)^2\cdot2x=6x(x^2+1)^2\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20607, 'គណនាដេរីវេនៃ \(y=\cos{\left(2 x + 1 \right)}\)។', NULL, '["\\(- 2 \\sin{\\left(2 x + 1 \\right)}\\)", "\\(2 \\sin{\\left(2 x + 1 \\right)}\\)", "\\(- 2 \\cos{\\left(2 x + 1 \\right)}\\)", "\\(- \\sin{\\left(2 x + 1 \\right)}\\)"]', 0, NULL, 1, 'mcq', '\((\cos u)''=-u''\sin u\) ជាមួយ \(u=2x+1\) ៖ \(y''=-2\sin(2x+1)\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20608, 'គណនាដេរីវេនៃ \(y=\operatorname{atan}{\left(x \right)}\)។', NULL, '["\\(\\dfrac{1}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{1}{1 - x^{2}}\\)", "\\(- \\dfrac{1}{x^{2} + 1}\\)", "\\(\\dfrac{1}{x^{2} + 1}\\)"]', 3, NULL, 1, 'mcq', '\(\dfrac{d}{dx}(\tan^{-1}x)=\dfrac1{1+x^2}\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20609, 'គណនាដេរីវេនៃ \(y=\sqrt{x^{2} - 1}\)។', NULL, '["\\(\\dfrac{x}{\\sqrt{x^{2} + 1}}\\)", "\\(\\dfrac{x}{\\sqrt{x^{2} - 1}}\\)", "\\(\\dfrac{2 x}{\\sqrt{x^{2} - 1}}\\)", "\\(\\dfrac{1}{2 \\sqrt{x^{2} - 1}}\\)"]', 1, NULL, 1, 'mcq', '\((\sqrt u)''=\dfrac{u''}{2\sqrt u}\) ជាមួយ \(u=x^2-1\) ៖ \(\dfrac{2x}{2\sqrt{x^2-1}}=\dfrac x{\sqrt{x^2-1}}\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20610, 'គណនាដេរីវេនៃ \(y=\tan{\left(x \right)}\)។', NULL, '["\\(- \\dfrac{1}{\\sin^{2}{\\left(x \\right)}}\\)", "\\(\\dfrac{1}{\\cos^{2}{\\left(x \\right)}}\\)", "\\(- \\dfrac{1}{\\cos^{2}{\\left(x \\right)}}\\)", "\\(\\dfrac{1}{\\sin^{2}{\\left(x \\right)}}\\)"]', 1, NULL, 1, 'mcq', '\((\tan x)''=\dfrac1{\cos^2x}=1+\tan^2x\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20611, 'គណនាដេរីវេនៃ \(y=\left(3 x^{2} + 5 x - 2\right)^{3}\)។', NULL, '["\\(3 \\left(3 x^{2} + 5 x - 2\\right)^{2}\\)", "\\(3 \\left(6 x + 5\\right) \\left(3 x^{2} + 5 x - 2\\right)^{3}\\)", "\\(\\left(6 x + 5\\right) \\left(3 x^{2} + 5 x - 2\\right)^{2}\\)", "\\(3 \\left(6 x + 5\\right) \\left(3 x^{2} + 5 x - 2\\right)^{2}\\)"]', 3, NULL, 2, 'mcq', 'តាង \(u=3x^2+5x-2\) ៖ \(y''=3u^2\cdot u''=3(3x^2+5x-2)^2(6x+5)\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20612, 'គណនាដេរីវេនៃ \(f(x)=x^{2} \cos{\left(3 x + 1 \right)}\)។', NULL, '["\\(3 x^{2} \\sin{\\left(3 x + 1 \\right)} + 2 x \\cos{\\left(3 x + 1 \\right)}\\)", "\\(- x^{2} \\sin{\\left(3 x + 1 \\right)} + 2 x \\cos{\\left(3 x + 1 \\right)}\\)", "\\(- 6 x \\sin{\\left(3 x + 1 \\right)}\\)", "\\(- 3 x^{2} \\sin{\\left(3 x + 1 \\right)} + 2 x \\cos{\\left(3 x + 1 \\right)}\\)"]', 3, NULL, 2, 'mcq', 'ដេរីវេផលគុណ \((uv)''=u''v+uv''\) ៖ \(2x\cos(3x+1)+x^2\cdot(-3\sin(3x+1))\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20613, 'គណនាដេរីវេនៃ \(y=x \operatorname{asin}{\left(x \right)}\)។', NULL, '["\\(\\dfrac{x}{\\sqrt{1 - x^{2}}} + \\operatorname{asin}{\\left(x \\right)}\\)", "\\(- \\dfrac{x}{\\sqrt{1 - x^{2}}} + \\operatorname{asin}{\\left(x \\right)}\\)", "\\(\\operatorname{asin}{\\left(x \\right)} + \\dfrac{1}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{x}{\\sqrt{1 - x^{2}}}\\)"]', 0, NULL, 2, 'mcq', '\((uv)''=u''v+uv''=\sin^{-1}x+\dfrac x{\sqrt{1-x^2}}\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20614, 'គណនាដេរីវេទី ២ នៃ \(g(x)=\dfrac{x^{2}}{x + 1}\)។', NULL, '["\\(\\dfrac{2 x}{\\left(x + 1\\right)^{3}}\\)", "\\(\\dfrac{2}{\\left(x + 1\\right)^{2}}\\)", "\\(\\dfrac{2}{\\left(x + 1\\right)^{3}}\\)", "\\(\\dfrac{x^{2} + 2 x}{\\left(x + 1\\right)^{2}}\\)"]', 2, NULL, 2, 'mcq', '\(g(x)=x-1+\dfrac1{x+1}\) ដូច្នេះ \(g''''(x)=\dfrac2{(x+1)^3}\)។', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20615, 'គណនាដេរីវេទី ៤ នៃ \(y=\sin{\left(2 x \right)}\)។', NULL, '["\\(16 \\cos{\\left(2 x \\right)}\\)", "\\(8 \\sin{\\left(2 x \\right)}\\)", "\\(16 \\sin{\\left(2 x \\right)}\\)", "\\(- 16 \\sin{\\left(2 x \\right)}\\)"]', 2, NULL, 2, 'mcq', '\(y''=2\cos2x\), \(y''''=-4\sin2x\), \(y''''''=-8\cos2x\), \(y^{(4)}=16\sin2x\)។', 'ដេរីវេលំដាប់ខ្ពស់', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20616, 'គណនាដេរីវេនៃ \(y=3 \sqrt[3]{x^{2} - 3 x + 1}\)។', NULL, '["\\(\\dfrac{2 x - 3}{\\left(x^{2} - 3 x + 1\\right)^{\\dfrac{2}{3}}}\\)", "\\(\\dfrac{2 x - 3}{3 \\left(x^{2} - 3 x + 1\\right)^{\\dfrac{2}{3}}}\\)", "\\(\\dfrac{6 x - 9}{\\left(x^{2} - 3 x + 1\\right)^{\\dfrac{2}{3}}}\\)", "\\(\\dfrac{2 x - 3}{\\sqrt[3]{x^{2} - 3 x + 1}}\\)"]', 0, NULL, 2, 'mcq', 'សរសេរ \(y=3u^{1/3}\) ជាមួយ \(u=x^2-3x+1\) ៖ \(y''=3\cdot\tfrac13u^{-2/3}u''=\dfrac{2x-3}{(x^2-3x+1)^{2/3}}\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20617, 'គណនាដេរីវេនៃ \(f(x)=x^{3} \tan{\left(x \right)}\)។', NULL, '["\\(\\dfrac{3 x^{2}}{\\cos^{2}{\\left(x \\right)}}\\)", "\\(\\dfrac{x^{3}}{\\cos^{2}{\\left(x \\right)}} + 3 x^{2} \\tan{\\left(x \\right)}\\)", "\\(- \\dfrac{x^{3}}{\\cos^{2}{\\left(x \\right)}} + 3 x^{2} \\tan{\\left(x \\right)}\\)", "\\(x^{3} \\tan^{2}{\\left(x \\right)} + 3 x^{2} \\tan{\\left(x \\right)}\\)"]', 1, NULL, 2, 'mcq', '\((uv)''=u''v+uv''\) ជាមួយ \(u=x^3,\ v=\tan x\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20618, 'គណនាដេរីវេនៃ \(y=\operatorname{acos}{\left(2 x \right)}\)។', NULL, '["\\(\\dfrac{2}{\\sqrt{1 - 4 x^{2}}}\\)", "\\(- \\dfrac{2}{\\sqrt{1 - 4 x^{2}}}\\)", "\\(- \\dfrac{1}{\\sqrt{1 - 4 x^{2}}}\\)", "\\(- \\dfrac{2}{\\sqrt{1 - 2 x^{2}}}\\)"]', 1, NULL, 2, 'mcq', '\((\cos^{-1}u)''=-\dfrac{u''}{\sqrt{1-u^2}}\) ជាមួយ \(u=2x\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20619, 'គេឱ្យសមីការ \(x^2+y^2=4\)។ គណនា \(\dfrac{dy}{dx}\) ត្រង់ចំណុច \((\sqrt2,\ \sqrt2)\)។', NULL, '["\\(1\\)", "\\(0\\)", "\\(-\\sqrt2\\)", "\\(-1\\)"]', 3, NULL, 2, 'mcq', '\(2x+2yy''=0\) ដូច្នេះ \(y''=-\dfrac xy=-\dfrac{\sqrt2}{\sqrt2}=-1\)។', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20620, 'គណនាដេរីវេនៃ \(f(x)=\dfrac{\sin{\left(x \right)}}{x}\)។', NULL, '["\\(\\dfrac{- \\sin{\\left(x \\right)} + \\cos{\\left(x \\right)}}{x^{2}}\\)", "\\(\\dfrac{x \\cos{\\left(x \\right)} - \\sin{\\left(x \\right)}}{x^{2}}\\)", "\\(\\dfrac{\\cos{\\left(x \\right)}}{x^{2}}\\)", "\\(- \\dfrac{\\sin{\\left(x \\right)}}{x} + \\dfrac{\\cos{\\left(x \\right)}}{x}\\)"]', 1, NULL, 2, 'mcq', '\(\left(\dfrac uv\right)''=\dfrac{u''v-uv''}{v^2}=\dfrac{x\cos x-\sin x}{x^2}\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20621, 'គណនាដេរីវេនៃ \(y=\left(2 x - \sin{\left(x \right)}\right)^{3}\)។', NULL, '["\\(3 \\left(2 x - \\sin{\\left(x \\right)}\\right)^{2} \\left(\\cos{\\left(x \\right)} + 2\\right)\\)", "\\(\\left(2 - \\cos{\\left(x \\right)}\\right) \\left(2 x - \\sin{\\left(x \\right)}\\right)^{2}\\)", "\\(3 \\left(2 - \\cos{\\left(x \\right)}\\right) \\left(2 x - \\sin{\\left(x \\right)}\\right)^{2}\\)", "\\(3 \\left(2 x - \\sin{\\left(x \\right)}\\right)^{2}\\)"]', 2, NULL, 2, 'mcq', '\(y''=3u^2u''\) ជាមួយ \(u=2x-\sin x\) ៖ \(u''=2-\cos x\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20622, 'គណនាដេរីវេនៃ \(y=\operatorname{atan}{\left(5 x \right)}\)។', NULL, '["\\(\\dfrac{1}{25 x^{2} + 1}\\)", "\\(\\dfrac{5}{1 - 25 x^{2}}\\)", "\\(\\dfrac{5}{5 x^{2} + 1}\\)", "\\(\\dfrac{5}{25 x^{2} + 1}\\)"]', 3, NULL, 2, 'mcq', '\((\tan^{-1}u)''=\dfrac{u''}{1+u^2}\) ជាមួយ \(u=5x\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20623, 'គណនាដេរីវេនៃ \(f(x)=\sin^{2}{\left(x^{2} \right)}\)។', NULL, '["\\(2 x \\sin{\\left(2 x^{2} \\right)}\\)", "\\(2 \\sin{\\left(x^{2} \\right)}\\)", "\\(4 x \\sin{\\left(x^{2} \\right)} \\cos{\\left(2 x^{2} \\right)}\\)", "\\(2 \\sin{\\left(x^{2} \\right)} \\cos{\\left(x^{2} \\right)}\\)"]', 0, NULL, 2, 'mcq', '\(y=[\sin(x^2)]^2\) ៖ \(y''=2\sin(x^2)\cos(x^2)\cdot2x=2x\sin2x^2\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20624, 'គណនាដេរីវេនៃ \(f(x)=\tan{\left(2 x^{3} - 5 x \right)}\)។', NULL, '["\\(\\dfrac{1}{\\cos^{2}{\\left(2 x^{3} - 5 x \\right)}}\\)", "\\(\\dfrac{2 x^{3} - 5 x}{\\cos^{2}{\\left(2 x^{3} - 5 x \\right)}}\\)", "\\(\\dfrac{6 x^{2} - 5}{\\cos^{2}{\\left(2 x^{3} - 5 x \\right)}}\\)", "\\(\\dfrac{6 x^{2} - 5}{\\sin^{2}{\\left(2 x^{3} - 5 x \\right)}}\\)"]', 2, NULL, 2, 'mcq', '\((\tan u)''=\dfrac{u''}{\cos^2u}\) ជាមួយ \(u=2x^3-5x\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20625, 'គេឱ្យសមីការ \(xy+y^2-x^2=5\) ដែលមានចំណុច \((1,\ 2)\)។ តម្លៃ \(y''''\) ត្រង់ចំណុចនេះ ស្មើនឹងប៉ុន្មាន ?', NULL, '["\\(0\\)", "\\(\\dfrac25\\)", "\\(-\\dfrac25\\)", "\\(\\dfrac{2}{5}\\cdot5\\)"]', 1, NULL, 3, 'mcq', '\(y''=\dfrac{2x-y}{x+2y}=0\) ត្រង់ \((1,2)\) ហើយ \(y''''=\dfrac{50}{(x+2y)^3}=\dfrac{50}{125}=\dfrac25\)។', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20626, 'គណនាដេរីវេនៃ \(y=\operatorname{asin}{\left(x^{2} \right)}\)។', NULL, '["\\(\\dfrac{1}{\\sqrt{1 - x^{4}}}\\)", "\\(\\dfrac{2 x}{\\sqrt{1 - x^{4}}}\\)", "\\(\\dfrac{2 x}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{2 x}{1 - x^{4}}\\)"]', 1, NULL, 3, 'mcq', '\((\sin^{-1}u)''=\dfrac{u''}{\sqrt{1-u^2}}\) ជាមួយ \(u=x^2\) ៖ \(\dfrac{2x}{\sqrt{1-x^4}}\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20627, 'គណនាដេរីវេទី ៥ នៃ \(f(x)=\dfrac{1}{x^{2}}\)។', NULL, '["\\(- \\dfrac{720}{x^{7}}\\)", "\\(- \\dfrac{720}{x^{8}}\\)", "\\(\\dfrac{720}{x^{7}}\\)", "\\(- \\dfrac{120}{x^{6}}\\)"]', 0, NULL, 3, 'mcq', '\(f^{(n)}(x)=(-1)^n(n+1)!\,x^{-(n+2)}\) ដូច្នេះ \(f^{(5)}(x)=-\dfrac{720}{x^7}\)។', 'ដេរីវេលំដាប់ខ្ពស់', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20628, 'គណនាដេរីវេនៃ \(y=\sin^{3}{\left(2 x + 1 \right)}\)។', NULL, '["\\(6 \\sin^{2}{\\left(2 x + 1 \\right)} \\cos{\\left(2 x + 1 \\right)}\\)", "\\(6 \\sin{\\left(2 x + 1 \\right)} \\cos^{2}{\\left(2 x + 1 \\right)}\\)", "\\(3 \\sin^{2}{\\left(2 x + 1 \\right)} \\cos{\\left(2 x + 1 \\right)}\\)", "\\(6 \\sin^{2}{\\left(2 x + 1 \\right)}\\)"]', 0, NULL, 3, 'mcq', 'ស្រទាប់បី ៖ \((w^3)''=3w^2w''\) ដែល \(w=\sin(2x+1)\) ហើយ \(w''=2\cos(2x+1)\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20629, 'គណនាដេរីវេទី ២ នៃ \(y=\operatorname{asin}{\left(x \right)}\)។', NULL, '["\\(\\dfrac{1}{\\left(1 - x^{2}\\right)^{\\dfrac{3}{2}}}\\)", "\\(\\dfrac{x}{\\sqrt{1 - x^{2}}}\\)", "\\(\\dfrac{x}{\\left(1 - x^{2}\\right)^{\\dfrac{3}{2}}}\\)", "\\(- \\dfrac{x}{\\left(1 - x^{2}\\right)^{\\dfrac{3}{2}}}\\)"]', 2, NULL, 3, 'mcq', '\(y''=(1-x^2)^{-1/2}\) ដូច្នេះ \(y''''=-\tfrac12(1-x^2)^{-3/2}\cdot(-2x)=\dfrac{x}{(1-x^2)^{3/2}}\)។', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20630, 'ការអះអាងមួយណាត្រឹមត្រូវ ?', NULL, '["\\(\\dfrac{d}{dx}\\left(\\tan^{-1}x+\\cot^{-1}x\\right)=\\dfrac{2}{1+x^2}\\)", "\\(\\dfrac{d}{dx}\\left(\\sin^{-1}x\\right)=\\dfrac{1}{1+x^2}\\)", "\\(\\dfrac{d}{dx}\\left(\\cos^{-1}x\\right)=\\dfrac{1}{\\sqrt{1-x^2}}\\)", "\\(\\dfrac{d}{dx}\\left(\\tan^{-1}x+\\cot^{-1}x\\right)=0\\) ដូច្នេះ \\(\\tan^{-1}x+\\cot^{-1}x\\) ជាចំនួនថេរ"]', 3, NULL, 3, 'mcq', '\(\dfrac1{1+x^2}-\dfrac1{1+x^2}=0\) ។ (ការពិត \(\tan^{-1}x+\cot^{-1}x=\dfrac\pi2\) ។) ឯខ្សែផ្សេងទៀតត្រូវជា \(\dfrac{1}{\sqrt{1-x^2}}\) (ស៊ីនុស) និង \(-\dfrac{1}{\sqrt{1-x^2}}\) (កូស៊ីនុស)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20631, 'គណនាដេរីវេនៃ \(f(x)=x^{2} \sin{\left(x^{3} \right)}\)។', NULL, '["\\(3 x^{2} \\cos{\\left(x^{3} \\right)} + 2 x \\sin{\\left(x^{3} \\right)}\\)", "\\(- 3 x^{4} \\cos{\\left(x^{3} \\right)} + 2 x \\sin{\\left(x^{3} \\right)}\\)", "\\(3 x^{4} \\cos{\\left(x^{3} \\right)} + 2 x \\sin{\\left(x^{3} \\right)}\\)", "\\(2 x \\cos{\\left(x^{3} \\right)}\\)"]', 2, NULL, 3, 'mcq', '\((uv)''=u''v+uv''\) ជាមួយ \(u=x^2\) និង \(v=\sin x^3\) ដែល \(v''=3x^2\cos x^3\)។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
