INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20632, 'កសិករម្នាក់ចង់ធ្វើរបងព័ទ្ធចម្ការរាងចតុកោណកែងដែលមានបរិមាត្រ \(400\ \text{m}\) ។ ផ្ទៃក្រឡាជាអនុគមន៍នៃទទឹង \(x\) គឺ \(A(x)=200x-x^2\) ដូចក្នុងរូប ។ តើ \(x\) ស្មើប៉ុន្មាន ដើម្បីឱ្យផ្ទៃក្រឡាធំបំផុត ?', 'g12sc-8152dc2fe3.svg', '["\\(x=50\\ \\text{m}\\)", "\\(x=400\\ \\text{m}\\)", "\\(x=100\\ \\text{m}\\)", "\\(x=200\\ \\text{m}\\)"]', 2, NULL, 3, 'mcq', '\(A''(x)=200-2x=0\) ដូច្នេះ \(x=100\) (ហើយ \(A''''=-2<0\) ជាអតិបរមា ; ទទឹងស្មើបណ្ដោយ គឺការ៉េ \(100\times100\))។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'pisa', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-6683ecca2f.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20633, 'រថយន្តលេងមួយដើរតាមបន្ទាត់ត្រង់ ដោយទីតាំង \(s(t)=t^3-6t^2+9t\) (m) ត្រង់ពេល \(t\) វិនាទី ដូចក្នុងរូប ។ តើល្បឿន \(v(2)\) (m/s) ស្មើប៉ុន្មាន ?', 'g12sc-6683ecca2f.svg', '["\\(-3\\)", "\\(3\\)", "\\(-12\\)", "\\(2\\)"]', 0, NULL, 3, 'mcq', '\(v(t)=s''(t)=3t^2-12t+9\) ដូច្នេះ \(v(2)=12-24+9=-3\) m/s (ចលនាថយក្រោយ)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'pisa', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
