INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20634, 'ចំណាយផលិត \(C(x)=0{,}5x^2+3x\) (លានរៀល) ដែល \(x\) ជាបរិមាណផលិត (រូបបង្ហាញខ្សែកោង និងបន្ទាត់ប៉ះត្រង់ \(x=8\)) ហើយ \(x=4t\) ត្រង់ពេល \(t\) ម៉ោង ។ គណនា \(\dfrac{dC}{dt}\) ត្រង់ \(t=2\) (លានរៀល/ម៉ោង) ។', 'g12sc-1accab3acb.svg', '["\\(56\\)", "\\(88\\)", "\\(11\\)", "\\(44\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{dC}{dt}=\dfrac{dC}{dx}\cdot\dfrac{dx}{dt}=(x+3)\cdot4\) ; ត្រង់ \(t=2\) មាន \(x=8\) ដូច្នេះ \((8+3)\times4=44\)។', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'pisa', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9aba1e1522.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20635, 'មុំរបស់ប៉ោលមួយ (rad) ត្រូវបានតាមដោយ \(\theta(t)=0{,}3\cos2t\) (រូបបង្ហាញ \(\theta\) និងល្បឿនមុំ \(\omega=\theta''\)) ។ គណនាល្បឿនមុំ \(\omega\) (rad/s) ត្រង់ \(t=\dfrac\pi4\) ។', 'g12sc-9aba1e1522.svg', '["\\(0{,}6\\)", "\\(-0{,}6\\)", "\\(-0{,}3\\)", "\\(0\\)"]', 1, NULL, 3, 'mcq', '\(\omega=\theta''=-0{,}6\sin2t\) ដូច្នេះ \(\omega\left(\dfrac\pi4\right)=-0{,}6\sin\dfrac\pi2=-0{,}6\) rad/s។', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'pisa', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
