INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20636, 'កាមេរ៉ាមើលវត្ថុដែលនៅឆ្ងាយ \(x\) ម៉ែត្រ ដោយមុំ \(\theta(x)=\tan^{-1}\dfrac x{10}\) (rad) ដូចក្នុងរូប ។ គណនាអត្រាបម្រែបម្រួល \(\theta''(x)\) ត្រង់ \(x=10\) (rad/m) ។', 'g12sc-88faeaf5dd.svg', '["\\(0{,}1\\)", "\\(0{,}5\\)", "\\(0{,}01\\)", "\\(0{,}05\\)"]', 3, NULL, 3, 'mcq', '\(\theta''(x)=\dfrac{\frac1{10}}{1+\frac{x^2}{100}}=\dfrac{10}{100+x^2}\) ដូច្នេះ \(\theta''(10)=\dfrac{10}{200}=0{,}05\)។', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'pisa', 1, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20637, 'គណនាដេរីវេនៃអនុគមន៍ \(y=(2x-3)^4\) ដោយប្រើរូបមន្តដេរីវេនៃអនុគមន៍បណ្ដាក់ ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(u=2x-3\) ដូច្នេះ \(y=u^4\) (1 ពិន្ទុ)
គណនា \(\dfrac{du}{dx}=2\) (1 ពិន្ទុ)
គណនា \(\dfrac{dy}{du}=4u^3\) (1 ពិន្ទុ)
ប្រើ \(\dfrac{dy}{dx}=\dfrac{dy}{du}\times\dfrac{du}{dx}=4u^3\times2=8u^3\) (1 ពិន្ទុ)
ជំនួស \(u=2x-3\) ៖ \(\dfrac{dy}{dx}=8(2x-3)^3\)។ (1 ពិន្ទុ)', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'easy', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20638, 'គណនាដេរីវេនៃអនុគមន៍ \(f(x)=x^2\cos(3x+1)\) ហើយគណនា \(f''(0)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើដេរីវេនៃផលគុណ \((uv)''=u''v+uv''\) ដែល \(u=x^2,\ v=\cos(3x+1)\) (1 ពិន្ទុ)
\(u''=2x\) (1 ពិន្ទុ)
ប្រើអនុគមន៍បណ្ដាក់ ៖ \(v''=-3\sin(3x+1)\) (1 ពិន្ទុ)
បូកបញ្ចូលគ្នា ៖ \(f''(x)=2x\cos(3x+1)-3x^2\sin(3x+1)\) (1 ពិន្ទុ)
ជំនួស \(x=0\) ៖ \(f''(0)=0-0=0\)។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20639, 'គណនាដេរីវេនៃអនុគមន៍ \(y=x\sin^{-1}2x\) ដែល \(|x|<\dfrac12\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើ \((uv)''=u''v+uv''\) ដែល \(u=x\) និង \(v=\sin^{-1}2x\) (1 ពិន្ទុ)
\(u''=1\) (1 ពិន្ទុ)
ប្រើ \((\sin^{-1}w)''=\dfrac{w''}{\sqrt{1-w^2}}\) ជាមួយ \(w=2x\) ៖ \(v''=\dfrac{2}{\sqrt{1-4x^2}}\) (1 ពិន្ទុ)
បូក ៖ \(y''=\sin^{-1}2x+x\cdot\dfrac2{\sqrt{1-4x^2}}\) (1 ពិន្ទុ)
ដូច្នេះ \(y''=\sin^{-1}2x+\dfrac{2x}{\sqrt{1-4x^2}}\)។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'medium', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20640, 'គេឱ្យរង្វង់ \(x^2+y^2=25\) ។ ក. រក \(y''\) ជាអនុគមន៍នៃ \(x\) និង \(y\) ។ ខ. រក \(y''''\) ។ គ. គណនាមេគុណប្រាប់ទិសនៃបន្ទាត់ប៉ះត្រង់ \((3,4)\) និងតម្លៃ \(y''''\) ត្រង់ចំណុចនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដេរីវេអង្គទាំងពីរ ៖ \(2x+2yy''=0\) ដូច្នេះ \(y''=-\dfrac xy\) ($y\ne0$) (1 ពិន្ទុ)
ខ. ដេរីវេ \(x+yy''=0\) ម្ដងទៀត ៖ \(1+y''^2+yy''''=0\) (1 ពិន្ទុ)
ដូច្នេះ \(y''''=-\dfrac{1+y''^2}{y}=-\dfrac{1+\frac{x^2}{y^2}}{y}=-\dfrac{x^2+y^2}{y^3}=-\dfrac{25}{y^3}\) (1 ពិន្ទុ)
គ. ត្រង់ \((3,4)\) ៖ \(y''=-\dfrac34\) (1 ពិន្ទុ)
\(y''''=-\dfrac{25}{4^3}=-\dfrac{25}{64}<0\) (រង្វង់ផ្នែកខាងលើកោងចុះ)។ (1 ពិន្ទុ)', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'medium', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20641, 'ដោយប្រើវិធីដេរីវេនៃផលចែក បង្ហាញថា ក. \((\tan x)''=\dfrac1{\cos^2x}\) ខ. \((\cot x)''=-\dfrac1{\sin^2x}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. សរសេរ \(\tan x=\dfrac{\sin x}{\cos x}\) ហើយប្រើ \(\left(\dfrac uv\right)''=\dfrac{u''v-uv''}{v^2}\) (1 ពិន្ទុ)
គណនា \((\tan x)''=\dfrac{\cos x\cos x-(-\sin x)\sin x}{\cos^2x}=\dfrac{\cos^2x+\sin^2x}{\cos^2x}\) (1 ពិន្ទុ)
ដូច្នេះ \((\tan x)''=\dfrac1{\cos^2x}=1+\tan^2x\) (1 ពិន្ទុ)
ខ. \(\cot x=\dfrac{\cos x}{\sin x}\) ៖ \((\cot x)''=\dfrac{-\sin x\sin x-\cos x\cos x}{\sin^2x}\) (1 ពិន្ទុ)
សម្រួល \(=\dfrac{-(\sin^2x+\cos^2x)}{\sin^2x}=-\dfrac1{\sin^2x}=-(1+\cot^2x)\)។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20642, 'ស្រាយបញ្ជាក់ដោយអនុមានរួមគណិតវិទ្យាថា ដេរីវេទី \(n\) នៃ \(y=\cos x\) គឺ \(y^{(n)}=\cos\left(x+\dfrac{n\pi}2\right)\) ចំពោះគ្រប់ \(n\in\mathbb{N}^*\)។', NULL, '[]', 0, NULL, 5, 'writing', 'មូលដ្ឋាន \(n=1\) ៖ \(y''=-\sin x=\cos\left(x+\dfrac\pi2\right)\) ពិត (1 ពិន្ទុ)
ឧបមា \(P(k)\) ៖ \(y^{(k)}=\cos\left(x+\dfrac{k\pi}2\right)\) ពិតចំពោះ \(k\ge1\) (1 ពិន្ទុ)
ដេរីវេ ៖ \(y^{(k+1)}=\left[\cos\left(x+\tfrac{k\pi}2\right)\right]''=-\sin\left(x+\tfrac{k\pi}2\right)\) (1 ពិន្ទុ)
ប្រើ \(-\sin\alpha=\cos\left(\alpha+\tfrac\pi2\right)\) ៖ \(y^{(k+1)}=\cos\left(x+\tfrac{k\pi}2+\tfrac\pi2\right)=\cos\left[x+\tfrac{(k+1)\pi}2\right]\) (1 ពិន្ទុ)
ដូច្នេះ \(P(k+1)\) ពិត ; តាមអនុមានរួម \(P(n)\) ពិតគ្រប់ \(n\in\mathbb{N}^*\)។ (1 ពិន្ទុ)', 'ដេរីវេលំដាប់ខ្ពស់', 'hard', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20643, 'ក. ប្រើអនុគមន៍ច្រាស \(x=\sin y\) ដោយ \(-\dfrac\pi2\le y\le\dfrac\pi2\) បង្ហាញថា \((\sin^{-1}x)''=\dfrac1{\sqrt{1-x^2}}\)។ ខ. វាយតម្លៃសេចក្ដីអះអាង "\(\sin^{-1}x\) មានដេរីវេគ្រប់ \(x\in[-1,1]\)" ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ពី \(x=\sin y\) ដេរីវេទាក់ទង \(x\) ៖ \(1=\cos y\cdot y''\) (1 ពិន្ទុ)
ដូច្នេះ \(y''=\dfrac1{\cos y}\) ដែល \(\cos y\ne0\) (1 ពិន្ទុ)
ដោយ \(-\dfrac\pi2\le y\le\dfrac\pi2\) នោះ \(\cos y\ge0\) ដូច្នេះ \(\cos y=\sqrt{1-\sin^2y}=\sqrt{1-x^2}\) ហើយ \(y''=\dfrac1{\sqrt{1-x^2}}\) (1 ពិន្ទុ)
ខ. ត្រង់ \(x=\pm1\) មាន \(y=\pm\dfrac\pi2\) ដូច្នេះ \(\cos y=0\) ភាគបែងស្មើសូន្យ (1 ពិន្ទុ)
ដូច្នេះដេរីវេមាន (កំណត់) តែចំពោះ \(-1<x<1\) (តង់សង់បញ្ឈរត្រង់ចុង) ; សេចក្ដីអះអាងមិនត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20644, 'គេឱ្យ \(f(x)=\dfrac{1}{x(x+1)}\)។ ក. សរសេរ \(f(x)=\dfrac ax+\dfrac b{x+1}\) ដោយរក \(a,b\)។ ខ. រកដេរីវេទី \(n\) \(f^{(n)}(x)\) ។ គ. គណនា \(f^{(5)}(1)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(1=a(x+1)+bx\) ៖ ដាក់ \(x=0\) បាន \(a=1\) ; ដាក់ \(x=-1\) បាន \(b=-1\) (1 ពិន្ទុ)
ដូច្នេះ \(f(x)=\dfrac1x-\dfrac1{x+1}\) (1 ពិន្ទុ)
ខ. ប្រើ \(\left(\dfrac1{x+c}\right)^{(n)}=\dfrac{(-1)^nn!}{(x+c)^{n+1}}\) ៖ \(f^{(n)}(x)=(-1)^nn!\left[\dfrac1{x^{n+1}}-\dfrac1{(x+1)^{n+1}}\right]\) (1 ពិន្ទុ)
គ. ជំនួស \(n=5,\ x=1\) ៖ \(f^{(5)}(1)=(-1)^5\,5!\left[1-\dfrac1{2^6}\right]\) (1 ពិន្ទុ)
ដូច្នេះ \(f^{(5)}(1)=-120\cdot\dfrac{63}{64}=-\dfrac{945}{8}=-118{,}125\)។ (1 ពិន្ទុ)', 'ដេរីវេលំដាប់ខ្ពស់', 'hard', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20645, 'ក. គណនា \(\dfrac{d}{dx}\left(\sin^{-1}x+\cos^{-1}x\right)\) ចំពោះ \(-1<x<1\) ។ ខ. ទាញថា \(\sin^{-1}x+\cos^{-1}x\) ជាចំនួនថេរ ហើយរកតម្លៃចំនួនថេរនេះ ។ គ. ប្រើលទ្ធផលដើម្បីបង្ហាញថា \(\dfrac{d}{dx}\cos^{-1}x=-\dfrac{d}{dx}\sin^{-1}x\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((\sin^{-1}x)''=\dfrac1{\sqrt{1-x^2}}\) និង \((\cos^{-1}x)''=-\dfrac1{\sqrt{1-x^2}}\) (1 ពិន្ទុ)
ផលបូក ៖ \(\dfrac1{\sqrt{1-x^2}}-\dfrac1{\sqrt{1-x^2}}=0\) (1 ពិន្ទុ)
ខ. ដេរីវេស្មើសូន្យលើចន្លោះ \((-1,1)\) ដូច្នេះអនុគមន៍ \(h(x)=\sin^{-1}x+\cos^{-1}x\) ជាចំនួនថេរ \(c\) (1 ពិន្ទុ)
រក \(c\) ដោយ \(x=0\) ៖ \(c=\sin^{-1}0+\cos^{-1}0=0+\dfrac\pi2=\dfrac\pi2\) (1 ពិន្ទុ)
គ. ដូច្នេះ \(\cos^{-1}x=\dfrac\pi2-\sin^{-1}x\) ហើយដេរីវេ ៖ \((\cos^{-1}x)''=-(\sin^{-1}x)''\)។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20646, 'កសិករម្នាក់មានរបង \(400\ \text{m}\) ដើម្បីព័ទ្ធចម្ការរាងចតុកោណកែង ទទឹង \(x\) បណ្ដោយ \(y\) ដូចក្នុងរូប ។ ក. បង្ហាញថា \(A(x)=200x-x^2\)។ ខ. រកដេរីវេ \(A''(x)\) ហើយរកតម្លៃ \(x\) ដែល \(A''(x)=0\)។ គ. ប្រើដេរីវេទី ២ បញ្ជាក់ថាជាអតិបរមា ហើយរកផ្ទៃក្រឡាអតិបរមា ។', 'g12sc-8152dc2fe3.svg', '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្រ \(2x+2y=400\) ដូច្នេះ \(y=200-x\) ហើយ \(A=xy=x(200-x)=200x-x^2\) (1 ពិន្ទុ)
ខ. \(A''(x)=200-2x\) (1 ពិន្ទុ)
ដោះស្រាយ \(200-2x=0\) បាន \(x=100\) (ដូច្នេះ \(y=100\)) (1 ពិន្ទុ)
គ. \(A''''(x)=-2<0\) ដូច្នេះ \(x=100\) ផ្ដល់អតិបរមា (1 ពិន្ទុ)
ផ្ទៃក្រឡាអតិបរមា \(A(100)=100\times100=10\,000\ \text{m}^2\) (ការ៉េ)។ (1 ពិន្ទុ)', 'ដេរីវេទី 2 និងដេរីវេអាប់លីស៊ីត', 'pisa', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20647, 'ទីតាំងនៃចំណុចមួយតាមបន្ទាត់ត្រង់ \(s(t)=t^3-6t^2+9t\) (m) ត្រង់ពេល \(t\) វិនាទី ដូចក្នុងរូប ។ ក. រកល្បឿន \(v(t)=s''(t)\) និងសំទុះ \(a(t)=s''''(t)\)។ ខ. ចំណុចឈប់ត្រង់ពេលណា ? គ. រកទីតាំងនៅពេលឈប់ និងសំទុះត្រង់ \(t=2\)។', 'g12sc-6683ecca2f.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(v(t)=3t^2-12t+9\) (m/s) (1 ពិន្ទុ)
\(a(t)=v''(t)=6t-12\) (m/s²) (1 ពិន្ទុ)
ខ. \(v=0\) ៖ \(3(t^2-4t+3)=3(t-1)(t-3)=0\) ដូច្នេះ \(t=1\) ឬ \(t=3\) វិនាទី (1 ពិន្ទុ)
គ. \(s(1)=1-6+9=4\) m ហើយ \(s(3)=27-54+27=0\) m (1 ពិន្ទុ)
\(a(2)=6(2)-12=0\) m/s² (ត្រង់ពេលនេះល្បឿនអប្បបរមា \(v(2)=-3\) m/s)។ (1 ពិន្ទុ)', 'ដេរីវេលំដាប់ខ្ពស់', 'pisa', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20648, 'ចំណាយផលិត \(C(x)=0{,}5x^2+3x\) (លានរៀល) ដែល \(x\) ជាចំនួនឯកតា ហើយការផលិតកើនតាមពេល \(x(t)=4t\) ឯកតា (t ម៉ោង) ដូចក្នុងរូប ។ ក. រក \(\dfrac{dC}{dx}\) និង \(\dfrac{dx}{dt}\)។ ខ. គណនា \(\dfrac{dC}{dt}\) ត្រង់ \(t=2\)។ គ. ផ្ទៀងផ្ទាត់ដោយសរសេរ \(C\) ជាអនុគមន៍នៃ \(t\) ដោយផ្ទាល់ ។', 'g12sc-1accab3acb.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{dC}{dx}=x+3\) ហើយ \(\dfrac{dx}{dt}=4\) (1 ពិន្ទុ)
ខ. \(\dfrac{dC}{dt}=\dfrac{dC}{dx}\cdot\dfrac{dx}{dt}=(x+3)\cdot4\) (1 ពិន្ទុ)
ត្រង់ \(t=2\) មាន \(x=4\times2=8\) (1 ពិន្ទុ)
ដូច្នេះ \(\dfrac{dC}{dt}=(8+3)\times4=44\) លានរៀល/ម៉ោង (1 ពិន្ទុ)
គ. \(C(t)=0{,}5(4t)^2+3(4t)=8t^2+12t\) ដូច្នេះ \(C''(t)=16t+12\) ហើយ \(C''(2)=44\) ត្រូវគ្នា។ (1 ពិន្ទុ)', 'និយមន័យនិងដេរីវេនៃអនុគមន៍បណ្ដាក់', 'pisa', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-120126d66d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20649, 'ដ្រូនមួយហោះនៅកម្ពស់ \(30\ \text{m}\) ដោយអ្នកសង្កេតនៅចម្ងាយផ្ដេក \(x\) ម៉ែត្រ ។ មុំសំលឹកឡើង \(\theta(x)=\tan^{-1}\dfrac{30}x\) (rad) ដូចក្នុងរូប ។ ក. គណនា \(\theta''(x)\)។ ខ. គណនា \(\theta''(40)\) ហើយបកស្រាយសញ្ញា ។ គ. ប្រៀបធៀបអត្រាត្រង់ \(x=40\) និង \(x=10\)។', 'g12sc-120126d66d.svg', '[]', 0, NULL, 5, 'writing', 'ក. ប្រើ \((\tan^{-1}u)''=\dfrac{u''}{1+u^2}\) ជាមួយ \(u=\dfrac{30}x\) ដែល \(u''=-\dfrac{30}{x^2}\) (1 ពិន្ទុ)
ដូច្នេះ \(\theta''(x)=\dfrac{-30/x^2}{1+900/x^2}=-\dfrac{30}{x^2+900}\) (1 ពិន្ទុ)
ខ. \(\theta''(40)=-\dfrac{30}{1\,600+900}=-\dfrac{30}{2\,500}=-0{,}012\) rad/m (1 ពិន្ទុ)
សញ្ញាអវិជ្ជមាន ៖ ដ្រូនកាន់តែឆ្ងាយ មុំសំលឹកកាន់តែតូច (1 ពិន្ទុ)
គ. \(\theta''(10)=-\dfrac{30}{1\,000}=-0{,}03\) rad/m ធំជាង \(0{,}012\) ក្នុងតម្លៃដាច់ខាត ៖ ក្បែរគល់មុំប្ដូរលឿនជាង។ (1 ពិន្ទុ)', 'ដេរីវេនៃអនុគមន៍ច្រាសត្រីកោណមាត្រ', 'pisa', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20650, 'មុំរបស់ប៉ោលមួយ \(\theta(t)=0{,}3\cos2t\) (rad) ដូចក្នុងរូប ។ ក. រកល្បឿនមុំ \(\omega=\theta''\) និងសំទុះមុំ \(\alpha=\theta''''\)។ ខ. បង្ហាញថា \(\theta''''+4\theta=0\)។ គ. វាយតម្លៃថា "សំទុះមុំធំបំផុតកើតឡើងនៅពេលល្បឿនមុំស្មើសូន្យ" ។', 'g12sc-9aba1e1522.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\omega=\theta''=-0{,}6\sin2t\) (ប្រើអនុគមន៍បណ្ដាក់) (1 ពិន្ទុ)
\(\alpha=\theta''''=-1{,}2\cos2t\) (1 ពិន្ទុ)
ខ. \(\theta''''+4\theta=-1{,}2\cos2t+4(0{,}3\cos2t)=-1{,}2\cos2t+1{,}2\cos2t=0\) (1 ពិន្ទុ)
គ. \(|\alpha|=1{,}2|\cos2t|\) ធំបំផុត \(=1{,}2\) កាលណា \(|\cos2t|=1\) (1 ពិន្ទុ)
ពេលនោះ \(\sin2t=0\) គឺ \(\omega=0\) ដូច្នេះសេចក្ដីអះអាងត្រឹមត្រូវ (ចុងរំញ័រ ល្បឿនស្មើសូន្យ សំទុះធំបំផុត)។ (1 ពិន្ទុ)', 'ដេរីវេលំដាប់ខ្ពស់', 'pisa', 0, '12SC', 'ដេរីវេនៃអនុគមន៍', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
